node -v && node --input-type=module -e '
import { checkSms } from "./bot.mjs";
const to = (o={}) => ({ phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...o });
const mk = (kind="marketing", body="Sale today", t=to()) => ({ kind, body, to: t });
const at = (iso) => new Date(iso);
const cases = [
  ["txn ok at 3am", mk("transactional","Your code is 123456", to()), at("2026-10-22T08:00:00Z"), {allowed:true,reason:null}],
  ["mkt 10:00 CDT", mk(), at("2026-10-22T15:00:00Z"), {allowed:true,reason:null}],
  ["mkt 07:59 CDT", mk(), at("2026-10-22T12:59:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["mkt 08:00 CDT", mk(), at("2026-10-22T13:00:00Z"), {allowed:true,reason:null}],
  ["mkt 20:59 CDT", mk(), at("2026-10-23T01:59:00Z"), {allowed:true,reason:null}],
  ["mkt 21:00 CDT", mk(), at("2026-10-23T02:00:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["mkt 08:00 CST after DST end", mk(), at("2026-11-01T14:00:00Z"), {allowed:true,reason:null}],
  ["mkt 07:59 CST after DST end", mk(), at("2026-11-01T13:59:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["mkt midnight local", mk(), at("2026-10-22T05:00:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["mkt no consent", mk("marketing","x",to({marketingConsent:false})), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"no_marketing_consent"}],
  ["mkt consent missing", mk("marketing","x",{phone:"+13125550142",timeZone:"America/Chicago",optedOutAt:null}), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"no_marketing_consent"}],
  ["mkt opted out", mk("marketing","x",to({optedOutAt:"2026-10-01T00:00:00Z"})), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"opted_out"}],
  ["txn opted out", mk("transactional","x",to({optedOutAt:"2026-10-01T00:00:00Z"})), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"opted_out"}],
  ["bad tz", mk("marketing","x",to({timeZone:"Mars/Olympus"})), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"invalid_time_zone"}],
  ["bad phone (UK)", mk("transactional","x",to({phone:"+442079460000"})), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"invalid_phone_number"}],
  ["bad kind", mk("promo"), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"invalid_kind"}],
  ["empty body", mk("transactional","   "), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"empty_body"}],
  ["invalid now", mk(), new Date("nope"), {allowed:false,reason:"invalid_time"}],
  ["undefined optedOutAt", mk("transactional","x",{phone:"+13125550142",timeZone:"America/Chicago",marketingConsent:true}), at("2026-10-22T15:00:00Z"), {allowed:false,reason:"invalid_recipient"}],
];
let fail = 0;
for (const [name, m, now, want] of cases) {
  const got = checkSms(m, now);
  const ok = got.allowed === want.allowed && got.reason === want.reason;
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
console.log(fail ? `${fail} FAILED` : "all passed");
'
echo "--- server TZ independence:"
for z in UTC Pacific/Kiritimati America/Los_Angeles; do TZ=$z node --input-type=module -e 'import { checkSms } from "./bot.mjs"; console.log(process.env.TZ, JSON.stringify(checkSms({kind:"marketing",body:"x",to:{phone:"+13125550142",timeZone:"America/Chicago",marketingConsent:true,optedOutAt:null}}, new Date("2026-10-22T15:00:00Z"))))'; done

